#include <signal.h>
#include <stdio.h>

void sig_int(int signo) {
    printf("SIGINT received\n");
}

int main() {
    if (signal(SIGINT, sig_int) == SIG_ERR) {
        printf("Failed to set signal handler\n");
        return 1;
    }
    printf("Program running... Press Ctrl+C to test SIGINT\n");
    while(1) {}  // Keep the program running
    return 0;
}
